										+ "'myField': {"
												+ "'type': 'date',"
												+ "'format': '" + elasticSearchClient.getDialect().getConcatenatedLocalDateDefaultMappingFormats() + "',"
												+ "'index': false"
										+ "}"
								+ "}"
						+ "}"
				)
		);

