return setup(new MassLoadingStrategy<Book,Integer>(){
  @Override public MassIdentifierLoader createIdentifierLoader(  LoadingTypeGroup<Book> includedTypes,  MassIdentifierSink<Integer> sink,  MassLoadingOptions options){
    return new MassIdentifierLoader(){
      private int i=0;
      @Override public void close(){
      }
      @Override public long totalCount(){
        return COUNT;
      }
      @Override public void loadNext() throws InterruptedException {
        sink.accept(Collections.singletonList(i++));
        if (i >= totalCount()) {
          sink.complete();
        }
      }
    }
;
  }
  @Override public MassEntityLoader<Integer> createEntityLoader(  LoadingTypeGroup<Book> includedTypes,  MassEntitySink<Book> sink,  MassLoadingOptions options){
    return new MassEntityLoader<Integer>(){
      @Override public void close(){
      }
      @Override public void load(      List<Integer> identifiers){
        throw new SimulatedFailure(exceptionMessage);
      }
    }
;
  }
}
);
}

