		if ( !unexpectedEvents.isEmpty() ) {
			description.appendText( "\nUnexpected logs:" );
			for ( LoggingEvent unexpected : unexpectedEvents ) {
				description.appendText( "\n\t" );
				description.appendText( unexpected.getRenderedMessage() );
			}
