		performRequest( ElasticsearchRequest.put()
			.pathComponent( indexName ).pathComponent( dialect.getTypeKeywordForNonMappingApi() ).pathComponent( id )
			.body( documentJsonObject )
			.param( "refresh", true )
			.build() );
	}

