		CompletableFuture<?> workFuture = new CompletableFuture<>();

		CompletableFuture<?> transactionFuture = runTransactionInDifferentThread(
				sessionFactory,
				null,
				expectedCommitStrategy, expectedRefreshStrategy,
				workFuture,
