    public static ExtractingTypePatternMatcher handleParameterizedType(ParameterizedType parameterizedTypePattern, Type typeToExtract) {
        Class<?> rawTypePattern = (Class<?>) parameterizedTypePattern.getRawType();
        Type[] typeArguments = parameterizedTypePattern.getActualTypeArguments();

        Integer typeVariableIndex = null;
        for (int i = 0; i < typeArguments.length; i++) {
            Type typeArgument = typeArguments[i];
            if (typeArgument instanceof TypeVariable) {
                if (typeVariableIndex == null) {
                    typeVariableIndex = i;
                    TypeVariable<?> typeVariable = (TypeVariable<?>) typeArgument;
                    Type[] upperBounds = typeVariable.getBounds();
                    if (!typeToExtract.equals(typeVariable)) {
                        throw new UnsupportedOperationException(
                            "Extracting anything other than the type variable when matching parameterized types is not supported"
                        );
                    }
                    if (upperBounds.length > 1 || !Object.class.equals(upperBounds[0])) {
                        throw new UnsupportedOperationException(
                            "Matching a parameterized type with bounded type arguments is not supported"
                        );
                    }
                } else {
                    throw new UnsupportedOperationException(
                        "Matching a parameterized type with multiple type variables in its arguments is not supported"
                    );
                }
            } else if (typeArgument instanceof WildcardType) {
                WildcardType wildcardTypeArgument = (WildcardType) typeArgument;
                Type[] upperBounds = wildcardTypeArgument.getUpperBounds();
                Type[] lowerBounds = wildcardTypeArgument.getLowerBounds();
                if (upperBounds.length > 1 || !Object.class.equals(upperBounds[0]) || lowerBounds.length > 0) {
                    throw new UnsupportedOperationException(
                        "Matching a parameterized type with bounded type arguments is not supported"
                    );
                }
            } else {
                throw new UnsupportedOperationException(
                    "Only type variables and wildcard types are supported as arguments to a parameterized type to match"
                );
            }
        }
        if (typeVariableIndex == null) {
            throw new UnsupportedOperationException(
                "Matching a parameterized type without a type variable in its arguments is not supported"
            );
        }
        return new ParameterizedTypeArgumentMatcher(rawTypePattern, typeVariableIndex);
    }
}
