		expectEntityIndexingFailureHandling(
				entityName, entityReferenceAsString,
				exceptionMessage, failingOperationAsString
		);

		doMassIndexingWithFailure(
				sessionFactory,
				ThreadExpectation.CREATED_AND_TERMINATED,
