        processor.beforeWorkSet(commitStrategy, refreshStrategy);

        Throwable throwable = processor.processWorks(works, reportBuilder); // Updated line

        if (throwable == null) {
            try {
                processor.afterSuccessfulWorkSet();
            } catch (RuntimeException e) {
                reportBuilder.throwable(e);
                throwable = e;
                // Removed the failingOperation call
            }
        }

        if (throwable == null) {
            indexingPlanFuture.complete(reportBuilder.build());
        } else {
            handleFailure(reportBuilder, throwable, processor);
        }
    }

    private void handleFailure(IndexIndexingPlanExecutionReport.Builder reportBuilder, Throwable throwable, LuceneWriteWorkProcessor processor) {
        IndexFailureContextImpl.Builder failureContextBuilder = new IndexFailureContextImpl.Builder();
        failureContextBuilder.throwable(throwable);
        failureContextBuilder.failingOperation("Processing works");

        for (LuceneSingleDocumentWriteWork<?> work : works) {
            reportBuilder.failingDocument(new LuceneDocumentReference(indexName, work.getDocumentId()));
            failureContextBuilder.uncommittedOperation(work.getInfo());
        }
        indexingPlanFuture.complete(reportBuilder.build());
        processor.getFailureHandler().handle(failureContextBuilder.build());
    }

    @Override
    public void markAsFailed(Throwable t) {
        indexingPlanFuture.completeExceptionally(t);
    }
}

