				.ifSupported(
						LuceneExtension.get(),
						c2 -> c2.fromLuceneSortField( new SortField( "sort3", Type.STRING ) )
				)
				.orElseFail()
				.end();

		SearchQuery<DocumentReference> query = searchTarget.query( sessionContext )
				.asReferences()
