						SearchQuery<List<?>> projectionQuery = searchTarget.query( sessionContext )
								.asProjections( searchTarget.projection().field( "nativeField_unsupportedProjection", Integer.class ).toProjection() )
								.predicate( root -> root.matchAll() )
