				.asReferences()
				.predicate( booleanPredicate )
				.build();
		assertThat( query )
				.hasReferencesHitsAnyOrder( INDEX_NAME, FIRST_ID, SECOND_ID, THIRD_ID )
				.hasHitCount( 3 );
	}

