				.build();
		assertThat( query )
				.hasReferencesHitsExactOrder( INDEX_NAME, FIRST_ID, SECOND_ID, THIRD_ID, FOURTH_ID, EMPTY_ID, FIFTH_ID );

		SearchSort sort1Desc = searchTarget.sort().extension( ElasticsearchExtension.get() )
