					.extension( ElasticsearchExtension.get() )
					.asJsonString( "{'type': 'keyword', 'doc_values': true}" )
					.createAccessor();
			sort5 = root.field( "sort5" )
					.extension( ElasticsearchExtension.get() )
					.asJsonString( "{'type': 'keyword', 'doc_values': true}" )
					.createAccessor();
		}
	}

}

