				.asReferences()
				.predicate( root -> root.bool( b -> {
					b.should( c -> c.extension( ElasticsearchExtension.get() )
							.fromJsonString( "{'match': {'string': 'text 1'}}" )
					);
					b.should( c -> c.extension( ElasticsearchExtension.get() )
							.fromJsonString( "{'match': {'integer': 2}}" )
					);
					b.should( c -> c.extension( ElasticsearchExtension.get() )
							.fromJsonString(
