												+ "'lon': -70"
											+ "}"
										+ "}"
									+ "}"
							)
					);
					// Also test using the standard DSL on a field defined with the extension
					b.should( c -> c.match().onField( "yearDays" ).matching( "'2018:12'" ) );
				} ) )
				.build();
