		return major;
	}

	public OptionalInt getMinor() {
		return minor == null ? OptionalInt.empty() : OptionalInt.of( minor );
	}

	public OptionalInt getMicro() {
		return micro == null ? OptionalInt.empty() : OptionalInt.of( micro );
	}

