	private void initData() {
		IndexIndexingPlan<? extends DocumentElement> plan = indexManager.createIndexingPlan();
		addDocumentToPlan(plan, FIRST_ID, "text 1", 37, 37, 37, "a", "z", "z");
		addDocumentToPlan(plan, SECOND_ID, null, 78, 78, 78, "z", "a", "z");
		addDocumentToPlan(plan, THIRD_ID, null, 13, 13, 13, "z", "z", "a");
		addDocumentToPlan(plan, FOURTH_ID, null, 89, 89, 89, "z", "z", "z");
		addDocumentToPlan(plan, FIFTH_ID, "text 2", 1, null, null, "zz", "zz", "zz");

		plan.execute().join();

		// Check that all documents are searchable
		StubMappingScope scope = indexManager.createScope();
		SearchQuery<DocumentReference> query = scope.query()
			.predicate( f -> f.matchAll() )
			.toQuery();
		assertThat( query ).hasDocRefHitsAnyOrder(
			INDEX_NAME,
			FIRST_ID, SECOND_ID, THIRD_ID, FOURTH_ID, FIFTH_ID
		);
	}

	private void addDocumentToPlan(IndexIndexingPlan<? extends DocumentElement> plan, String id, String stringValue, Integer nativeFieldValue, Integer nativeFieldConvertedValue, Integer nativeFieldUnsupportedProjectionValue, String sort1Value, String sort2Value, String sort3Value) {
		plan.add(referenceProvider(id), document -> {
			if (stringValue != null) {
				document.addValue(indexMapping.string, stringValue);
			}
			if (nativeFieldValue != null) {
				document.addValue(indexMapping.nativeField, nativeFieldValue);
			}
			if (nativeFieldConvertedValue != null) {
				document.addValue(indexMapping.nativeField_converted, nativeFieldConvertedValue);
			}
			if (nativeFieldUnsupportedProjectionValue != null) {
				document.addValue(indexMapping.nativeField_unsupportedProjection, nativeFieldUnsupportedProjectionValue);
			}
			document.addValue(indexMapping.sort1, sort1Value);
			document.addValue(indexMapping.sort2, sort2Value);
			document.addValue(indexMapping.sort3, sort3Value);
		});
	}

	private static class IndexMapping {
		final IndexFieldReference<Integer> integer;
		final IndexFieldReference<String> string;
		final IndexFieldReference<GeoPoint> geoPoint;
		final IndexFieldReference<Integer> nativeField;
		final IndexFieldReference<Integer> nativeField_converted;
		final IndexFieldReference<Integer> nativeField_unsupportedProjection;
		final IndexFieldReference<Integer> nativeField_invalidFieldPath;

		final IndexFieldReference<String> sort1;
		final IndexFieldReference<String> sort2;
		final IndexFieldReference<String> sort3;

		IndexMapping(IndexSchemaElement root) {
			integer = root.field(
				"integer",
				f -> f.asInteger().projectable( Projectable.YES )
			)
			.toReference();
			string = root.field(
				"string",
				f -> f.asString().projectable( Projectable.YES )
			)
			.toReference();
			geoPoint = root.field(
				"geoPoint",
				f -> f.asGeoPoint().projectable( Projectable.YES )
			)
			.toReference();
			nativeField = root.field(
				"nativeField",
				f -> f.extension( LuceneExtension.get() )
					.asNative( Integer.class, LuceneExtensionIT::contributeNativeField, LuceneExtensionIT::fromNativeField )
			)
			.toReference();
			nativeField_converted = root.field(
				"nativeField_converted",
				f -> f.extension( LuceneExtension.get() )
					.asNative( Integer.class, LuceneExtensionIT::contributeNativeField, LuceneExtensionIT::fromNativeField )
					.projectionConverter( ValueWrapper.class, ValueWrapper.fromIndexFieldConverter() )
			)
			.toReference();
			nativeField_unsupportedProjection = root.field(
				"nativeField_unsupportedProjection",
				f -> f.extension( LuceneExtension.get() )
					.asNative( Integer.class, LuceneExtensionIT::contributeNativeField )
			)
			.toReference();
			nativeField_invalidFieldPath = root.field(
				"nativeField_invalidFieldPath",
				f -> f.extension( LuceneExtension.get() )
					.asNative( Integer.class, LuceneExtensionIT::contributeNativeFieldInvalidFieldPath )
			)
			.toReference();

			sort1 = root.field( "sort1", f -> f.asString().sortable( Sortable.YES ) )
			.toReference();
			sort2 = root.field( "sort2", f -> f.asString().sortable( Sortable.YES ) )
			.toReference();
